import unittest
from candidate import smallest_change

class TestSmallestChange(unittest.TestCase):
    def test_example_first(self):
        self.assertEqual(smallest_change([1, 2, 3, 5, 4, 7, 9, 6]), 4)

    def test_example_second(self):
        self.assertEqual(smallest_change([1, 2, 3, 4, 3, 2, 2]), 1)

    def test_example_third(self):
        self.assertEqual(smallest_change([1, 2, 3, 2, 1]), 0)

    def test_empty_list_returns_zero(self):
        self.assertEqual(smallest_change([]), 0)

    def test_single_element_returns_zero(self):
        self.assertEqual(smallest_change([10]), 0)

    def test_two_equal_elements_returns_zero(self):
        self.assertEqual(smallest_change([3, 3]), 0)

    def test_two_unequal_elements_returns_one(self):
        self.assertEqual(smallest_change([1, 2]), 1)

    def test_even_length_array(self):
        self.assertEqual(smallest_change([1, 2, 3, 4, 5, 6]), 3)

    def test_odd_length_array_palindrome(self):
        self.assertEqual(smallest_change([0, 1, 2, 3, 2, 1, 0]), 0)

    def test_all_identical_elements(self):
        self.assertEqual(smallest_change([7, 7, 7, 7]), 0)

    def test_negative_integers(self):
        self.assertEqual(smallest_change([-5, -4, -3, -4, -5]), 0)

    def test_mixed_sign_numbers(self):
        self.assertEqual(smallest_change([1, -2, -2, 1]), 0)

    def test_none_input_raises_type_error(self):
        with self.assertRaises(TypeError):
            smallest_change(None)

    def test_integer_input_raises_type_error(self):
        with self.assertRaises(TypeError):
            smallest_change(42)

if __name__ == '__main__':
    unittest.main()
